      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"140\" y=\"55\" width=\"360\" height=\"250\" rx=\"12\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><circle cx=\"156\" cy=\"70\" r=\"4\" fill=\"#ff5f57\"/><circle cx=\"170\" cy=\"70\" r=\"4\" fill=\"#febc2e\"/><circle cx=\"184\" cy=\"70\" r=\"4\" fill=\"#28c840\"/><rect x=\"198\" y=\"62\" width=\"290\" height=\"16\" rx=\"8\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><line x1=\"140\" y1=\"85\" x2=\"500\" y2=\"85\" stroke=\"#2a2c4e\" stroke-width=\"1\"/><rect x=\"180\" y=\"110\" width=\"280\" height=\"40\" rx=\"8\" fill=\"#7c5cff\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"320\" y=\"136\" fill=\"#fff\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">Linus Torvalds</text><text x=\"320\" y=\"190\" fill=\"#9a9cc4\" font-size=\"14\" font-weight=\"400\" text-anchor=\"middle\">(internetdan olindi)</text><rect x=\"240\" y=\"230\" width=\"160\" height=\"36\" rx=\"8\" fill=\"none\" stroke=\"#c6ff4f\" stroke-width=\"1.5\"/><text x=\"320\" y=\"253\" fill=\"#c6ff4f\" font-size=\"13\" font-weight=\"600\" text-anchor=\"middle\">✓ jonli ma'lumot</text></svg>"
