        "sarlavha": "Obyektlar massivi",
        "izoh": "Har element: id, matn, bajarildi.",
        "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"120\" y=\"70\" width=\"400\" height=\"40\" rx=\"8\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"150\" y=\"95\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">id</text><text x=\"240\" y=\"95\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">matn</text><text x=\"430\" y=\"95\" fill=\"#7c5cff\" font-size=\"13\" font-weight=\"700\" text-anchor=\"start\">bajarildi</text><rect x=\"120\" y=\"115\" width=\"400\" height=\"45\" rx=\"0\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"150\" y=\"143\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">1</text><text x=\"240\" y=\"143\" fill=\"#ecebff\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">Dars qilish</text><text x=\"455\" y=\"143\" fill=\"#ff5f57\" font-size=\"13\" font-weight=\"400\" text-anchor=\"middle\">false</text><rect x=\"120\" y=\"165\" width=\"400\" height=\"45\" rx=\"0\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><text x=\"150\" y=\"193\" fill=\"#38e1c8\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">2</text><text x=\"240\" y=\"193\" fill=\"#ecebff\" font-size=\"14\" font-weight=\"400\" text-anchor=\"start\">Kitob o'qish</text><text x=\"455\" y=\"193\" fill=\"#c6ff4f\" font-size=\"13\" font-weight=\"400\" text-anchor=\"middle\">true</text><text x=\"320\" y=\"250\" fill=\"#9a9cc4\" font-size=\"13\" font-weight=\"400\" text-anchor=\"middle\">filter · find · map bilan boshqarasiz</text></svg>"
