      "svg": "<svg class=\"vz-svg\" viewBox=\"0 0 640 360\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" preserveAspectRatio=\"xMidYMid meet\"><defs><marker id=\"vzar\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6 Z\" fill=\"#6d6f9c\"/></marker></defs><rect x=\"150\" y=\"55\" width=\"340\" height=\"250\" rx=\"12\" fill=\"#0b0c1a\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><circle cx=\"166\" cy=\"70\" r=\"4\" fill=\"#ff5f57\"/><circle cx=\"180\" cy=\"70\" r=\"4\" fill=\"#febc2e\"/><circle cx=\"194\" cy=\"70\" r=\"4\" fill=\"#28c840\"/><rect x=\"208\" y=\"62\" width=\"270\" height=\"16\" rx=\"8\" fill=\"#1b1c36\" stroke=\"#2a2c4e\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"85\" x2=\"490\" y2=\"85\" stroke=\"#2a2c4e\" stroke-width=\"1\"/><text x=\"185\" y=\"110\" fill=\"#ecebff\" font-size=\"16\" font-weight=\"400\" text-anchor=\"start\">• Dars</text><text x=\"185\" y=\"150\" fill=\"#ecebff\" font-size=\"16\" font-weight=\"400\" text-anchor=\"start\">• Sport</text><text x=\"185\" y=\"190\" fill=\"#ecebff\" font-size=\"16\" font-weight=\"400\" text-anchor=\"start\">• Kino</text><text x=\"185\" y=\"250\" fill=\"#6d6f9c\" font-size=\"13\" font-weight=\"400\" text-anchor=\"start\">.map() bilan chizildi</text></svg>"
