        "p": "Deploydan oldin ilovani sinchiklab sinaysiz. Turli holatlarni tekshiring: bo'sh ma'lumot, noto'g'ri kirish, ko'p foydalanuvchi bir vaqtda, internet uzilishi. Mashinani sotishdan oldin har tugmasini sinagandek — foydalanuvchi xatoga uchramasin."
