        "p": "Sinash paytida topilgan har xatoni tuzating va qayta sinang. Turli brauzer va qurilmalarda tekshiring (telefon, kompyuter). Bu bosqich zerikarli tuyulishi mumkin, lekin u ilovangizni ishonchli qiladi — foydalanuvchi buni qadrlaydi."
