    "material": [
      {
        "s": "Yo'l yakuni — Ilova muhandisi",
        "p": "Mana yakuniy nuqta! Full-stack ilovangizni himoya qilib, 'Ilova muhandisi' darajasini olasiz. Endi siz ma'lumot saqlaydigan, foydalanuvchili, internetda yashaydigan haqiqiy ilova qura olasiz. Basic'dagi oddiy HTML sahifadan bu yergacha — katta yo'lni bosib o'tdingiz."
      },
      {
        "s": "Basic'dan Pro'gacha",
        "p": "Bir jumlada: 'brauzerda ishlaydigan sahifa'dan (Yaratuvchi) 'internetda yashaydigan haqiqiy ilova'gacha (Ilova muhandisi). O'z o'yinchog'ingiz real mahsulotga aylandi. Bu farqni siz o'z qo'lingiz bilan yaratdingiz va his qildingiz."
      },
      {
        "s": "Keyingi qadam",
        "p": "Yo'l shu bilan tugamaydi — endi eshiklar ochiq: freelance (kichik buyurtmalar), jamoada ishlash, o'z startapingiz, yangi texnologiyalar (React, mobil ilovalar). Eng muhimi — endi sizda poydevor bor: mustaqil o'rganish va real mahsulot qurish ko'nikmasi."
      }
    ],
