    "nom": "1-oylik imtihon",
    "qamrov": "1-12 darslar",
    "mavzu": "Web asoslari, HTML/CSS va algoritmik fikrlash boshlanishi",
    "kirish": "Birinchi oy yakuni. HTML tuzilishi, CSS bezash va layout, internet asoslari, raqamli xavfsizlik hamda JavaScript va algoritmik fikrlashning dastlabki tushunchalari tekshiriladi.",
    "nazariy": [
      "HTML nima va teg qanday ishlaydi? Ochilish va yopilish tegiga misol keltiring.",
      "CSS'da element, class va id selektorlari orasidagi farq nimada?",
      "Box model qatlamlarini (margin, border, padding, content) tushuntiring.",
      "Internetda so'rov-javob (client-server) qanday ishlaydi? URL qismlarini ayting.",
      "Kuchli parol qanday bo'ladi? Kamida 3 ta qoida keltiring.",
      "let va const farqi nimada? Har biriga misol.",
      "Algoritm nima? Kundalik hayotdan misol keltiring.",
      "Dekompozitsiya nima va nega dasturchiga kerak?"
    ],
    "amaliy": "Bezatilgan 'Men haqimda' sahifasini yasang: sarlavha, rasm, 3 ta fakt (ro'yxat) va havola. CSS bilan rang, shrift va joylashuv bering. So'ng foydalanuvchidan ismini prompt bilan so'rab, konsolda salomlashuvchi kichik skript yozing.",
    "mezon": [
      "HTML tuzilishi to'g'ri (sarlavha, ro'yxat, havola, rasm)",
      "CSS bezash qo'llangan (rang, shrift, joylashuv)",
      "prompt va console.log ishlaydi",
      "Kod toza va xatosiz"
    ],
